// Synthetic local receipt generated by Flutter, no external font/image calls.
import 'dart:ui' as ui;
import 'dart:typed_data';
import 'package:flutter/painting.dart';
Future<Uint8List> offlineReceipt({required int amount}) async {
 final recorder=ui.PictureRecorder();final canvas=ui.Canvas(recorder);
 canvas.drawRect(const ui.Rect.fromLTWH(0,0,720,760),ui.Paint()..color=const ui.Color(0xFFF6F7FA));
 final lines=['إيصال معاينة محلي','غير صالح لأي عملية مالية','العربون التجريبي: $amount د.ع','المرجع: معاينة فقط ٠٠٠١','لا محفظة ولا تحويل حقيقي','لم يُرسل الملف إلى أي خادم'];
 for(var i=0;i<lines.length;i++){
  final text=TextPainter(text:TextSpan(text:lines[i],style:TextStyle(fontFamily:'Cairo',fontSize:i==0?38:28,color:const ui.Color(0xFF0F172A))),textDirection:ui.TextDirection.rtl)..layout(maxWidth:640);
  text.paint(canvas,ui.Offset(40,60+i*105));text.dispose();
 }
 final picture=recorder.endRecording();final image=await picture.toImage(720,760);final bytes=await image.toByteData(format:ui.ImageByteFormat.png);image.dispose();picture.dispose();return bytes!.buffer.asUint8List();
}
